{
  "tool": "route_task",
  "description": "REQUIRED every turn before planning or edits. Returns ranked agents, skills, rules, and memory under a token budget. Pass user_message, current_working_directory, and open_files. Session digests from Cursor/OpenCode/Codex/Gemini/Antigravity and team memory are only injected here.",
  "inputSchema": {
    "type": "object",
    "properties": {
      "current_working_directory": {
        "default": null,
        "type": [
          "string",
          "null"
        ]
      },
      "limits": {
        "$ref": "#/$defs/RouteLimits",
        "default": {
          "agents": 2,
          "memory": 5,
          "rules": 5,
          "skills": 3
        }
      },
      "max_tokens": {
        "default": 500,
        "format": "uint",
        "minimum": 0,
        "type": "integer"
      },
      "open_files": {
        "default": [],
        "items": {
          "type": "string"
        },
        "type": "array"
      },
      "phase": {
        "default": null,
        "type": [
          "string",
          "null"
        ]
      },
      "task_kind": {
        "default": null,
        "type": [
          "string",
          "null"
        ]
      },
      "user_message": {
        "type": "string"
      }
    },
    "required": [
      "user_message"
    ],
    "$defs": {
      "RouteLimits": {
        "properties": {
          "agents": {
            "default": 2,
            "format": "uint",
            "minimum": 0,
            "type": "integer"
          },
          "memory": {
            "default": 5,
            "format": "uint",
            "minimum": 0,
            "type": "integer"
          },
          "rules": {
            "default": 5,
            "format": "uint",
            "minimum": 0,
            "type": "integer"
          },
          "skills": {
            "default": 3,
            "format": "uint",
            "minimum": 0,
            "type": "integer"
          }
        },
        "type": "object"
      }
    },
    "$schema": "https://json-schema.org/draft/2020-12/schema",
    "title": "RouteTaskParams"
  }
}

{
  "tool": "list_directory",
  "description": "List files and subdirectories in a directory with types, sizes, and timestamps. Token-bounded alternative to host ls.",
  "inputSchema": {
    "type": "object",
    "properties": {
      "allow_blocked_paths": {
        "default": false,
        "type": "boolean"
      },
      "current_working_directory": {
        "default": null,
        "type": [
          "string",
          "null"
        ]
      },
      "include_hidden": {
        "default": false,
        "type": "boolean"
      },
      "max_entries": {
        "default": 100,
        "format": "uint",
        "minimum": 0,
        "type": "integer"
      },
      "max_tokens": {
        "default": 500,
        "format": "uint",
        "minimum": 0,
        "type": "integer"
      },
      "path": {
        "type": "string"
      }
    },
    "required": [
      "path"
    ],
    "$schema": "https://json-schema.org/draft/2020-12/schema",
    "title": "ListDirectoryParams"
  }
}
